const rows = $input.all().map(item => item.json);

const today = new Date();

// Use UAE local date instead of UTC
const assessmentDate = new Intl.DateTimeFormat('en-CA', {
  timeZone: 'Asia/Dubai',
  year: 'numeric',
  month: '2-digit',
  day: '2-digit'
}).format(today);

const normalize = value =>
  String(value ?? '').trim().toLowerCase();

const parseDate = value => {
  if (!value) return null;

  const date = new Date(value);

  if (Number.isNaN(date.getTime())) {
    return null;
  }

  date.setHours(0, 0, 0, 0);
  return date;
};

// Set today's date to midnight for overdue comparisons
const todayForComparison = new Date(
  today.getFullYear(),
  today.getMonth(),
  today.getDate()
);

const openActions = rows.filter(row => {
  const status = normalize(row.Status);

  return ![
    'completed',
    'closed',
    'cancelled',
    'canceled'
  ].includes(status);
});

const overdueActions = openActions.filter(row => {
  const dueDate = parseDate(row['Due Date']);

  return dueDate && dueDate < todayForComparison;
});

const highPriorityOverdue = overdueActions.filter(row => {
  const priority = normalize(row.Priority);

  return ['high', 'critical'].includes(priority);
});

const actionsWithoutOwner = openActions.filter(row => {
  return !String(row.Owner ?? '').trim();
});

const overduePercentage =
  openActions.length > 0
    ? (overdueActions.length / openActions.length) * 100
    : 0;

const ownershipPercentage =
  openActions.length > 0
    ? (actionsWithoutOwner.length / openActions.length) * 100
    : 0;

let overduePenalty = 0;

if (overduePercentage > 50) {
  overduePenalty = 50;
} else if (overduePercentage > 30) {
  overduePenalty = 40;
} else if (overduePercentage > 20) {
  overduePenalty = 30;
} else if (overduePercentage > 10) {
  overduePenalty = 20;
} else if (overduePercentage > 0) {
  overduePenalty = 10;
}

const highPriorityPenalty = Math.min(
  highPriorityOverdue.length * 10,
  30
);

let ownershipPenalty = 0;

if (ownershipPercentage > 30) {
  ownershipPenalty = 20;
} else if (ownershipPercentage > 10) {
  ownershipPenalty = 10;
} else if (ownershipPercentage > 0) {
  ownershipPenalty = 5;
}

const actionScore = Math.max(
  0,
  100 -
    overduePenalty -
    highPriorityPenalty -
    ownershipPenalty
);

return [
  {
    json: {
      assessment_date: assessmentDate,
      total_actions: rows.length,
      open_actions: openActions.length,
      overdue_actions: overdueActions.length,
      overdue_percentage: Number(overduePercentage.toFixed(2)),
      high_priority_overdue_actions: highPriorityOverdue.length,
      actions_without_owner: actionsWithoutOwner.length,
      overdue_penalty: overduePenalty,
      high_priority_penalty: highPriorityPenalty,
      ownership_penalty: ownershipPenalty,
      action_score: actionScore
    }
  }
];

