  const date = new Date(value);

  if (Number.isNaN(date.getTime())) {
    return null;
  }

  return date;
};

// --------------------------------------------------
// 1. Deduplicate issues using Issue Key
// --------------------------------------------------

const uniqueIssueMap = new Map();

for (const issue of rows) {
  const issueKey =
    String(issue['Issue Key'] ?? '').trim() ||
    String(issue['Issue ID'] ?? '').trim();

  if (!issueKey) {
    continue;
  }

  // Keep first occurrence
  if (!uniqueIssueMap.has(issueKey)) {
    uniqueIssueMap.set(issueKey, issue);
  }
}

const issues = Array.from(uniqueIssueMap.values());

const duplicateIssuesRemoved =
  rows.length - issues.length;

// --------------------------------------------------
// 2. Identify open issues
// --------------------------------------------------

const openIssues = issues.filter(issue => {
  const status = normalize(issue.Status);

  return ![
    'closed',
    'resolved',
    'cancelled',
    'canceled'
  ].includes(status);
});

// --------------------------------------------------
// 3. Critical issues
// --------------------------------------------------

const criticalIssues = openIssues.filter(issue => {
  const severity = normalize(issue.Severity);

  return severity === 'critical';
});

// --------------------------------------------------
// 4. Issues without owners
// --------------------------------------------------

const issuesWithoutOwner = openIssues.filter(issue => {
  return isPlaceholder(issue.Owner);
});

// --------------------------------------------------
// 5. Stale issues
//    Open issue not updated for more than 7 days
// --------------------------------------------------

const staleIssues = openIssues.filter(issue => {
  const lastUpdated = parseDate(issue['Last Updated']);

  if (!lastUpdated) {
    return false;
  }

  const ageInDays =
    (now.getTime() - lastUpdated.getTime()) /
    (1000 * 60 * 60 * 24);

  return ageInDays > 7;
});

// --------------------------------------------------
// 6. Penalties
// --------------------------------------------------

const criticalIssuePenalty = Math.min(
  criticalIssues.length * 30,
  60
);

const ownershipPenalty = Math.min(
  issuesWithoutOwner.length * 10,
  20
);

const staleIssuePenalty = Math.min(
  staleIssues.length * 10,
  20
);

// --------------------------------------------------
// 7. Final Issue Health Score
// --------------------------------------------------

const issueScore = Math.max(
  0,
  100 -
    criticalIssuePenalty -
    ownershipPenalty -
    staleIssuePenalty
);

// --------------------------------------------------
// 8. Output
// --------------------------------------------------

return [
  {
    json: {
      assessment_date: assessmentDate,

      source_issue_rows: rows.length,
      unique_issues: issues.length,
      duplicate_issues_removed: duplicateIssuesRemoved,

      open_issues: openIssues.length,
      critical_issues: criticalIssues.length,
      issues_without_owner: issuesWithoutOwner.length,
      stale_issues: staleIssues.length,

      critical_issue_penalty: criticalIssuePenalty,
      ownership_penalty: ownershipPenalty,
      stale_issue_penalty: staleIssuePenalty,

      issue_score: issueScore
    }
  }
];

