const items = $input.all().map(item => item.json);

// Combine all four health component outputs
const data = Object.assign({}, ...items);

const riskScore = Number(data.risk_score ?? 0);
const issueScore = Number(data.issue_score ?? 0);
const dependencyScore = Number(data.dependency_score ?? 0);
const assumptionScore = Number(data.assumption_score ?? 0);

// RAID weighting
const raidScore = Math.round(
  riskScore * 0.35 +
  issueScore * 0.35 +
  dependencyScore * 0.20 +
  assumptionScore * 0.10
);

// Base RAG status
let calculatedRaidStatus;

if (raidScore >= 80) {
  calculatedRaidStatus = 'Green';
} else if (raidScore >= 60) {
  calculatedRaidStatus = 'Amber';
} else {
  calculatedRaidStatus = 'Red';
}

// Critical issue override
const criticalIssues =
  Number(data.critical_issues ?? 0);

const criticalOverride =
  criticalIssues > 0;

const finalRaidStatus =
  criticalOverride
    ? 'Red'
    : calculatedRaidStatus;

return [
  {
    json: {
      assessment_date: data.assessment_date,

      risk_score: riskScore,
      issue_score: issueScore,
      dependency_score: dependencyScore,
      assumption_score: assumptionScore,

      risk_weight: 35,
      issue_weight: 35,
      dependency_weight: 20,
      assumption_weight: 10,

      raid_score: raidScore,

      calculated_raid_status:
        calculatedRaidStatus,

      critical_issues: criticalIssues,
      critical_override: criticalOverride,

      raid_status: finalRaidStatus
    }
  }
];

const rows = $input.all().map(item => item.json);

const now = new Date();

const assessmentDate = new Intl.DateTimeFormat('en-CA', {
  timeZone: 'Asia/Dubai',
  year: 'numeric',
  month: '2-digit',
  day: '2-digit'
}).format(now);

const normalize = value =>
  String(value ?? '').trim().toLowerCase();

const parseDate = value => {
  if (!value) return null;

  // Handles YYYY-MM-DD reliably
  const match = String(value).match(
    /^(\d{4})-(\d{2})-(\d{2})$/
  );

  if (match) {
    return new Date(
      Number(match[1]),
      Number(match[2]) - 1,
      Number(match[3])
    );
  }

  const date = new Date(value);

  if (Number.isNaN(date.getTime())) {
    return null;
  }

  return date;
};

const [assessmentYear, assessmentMonth, assessmentDay] =
  assessmentDate.split('-').map(Number);

const today = new Date(
  assessmentYear,
  assessmentMonth - 1,
  assessmentDay
);

const daysBetween = (start, end) => {
  const millisecondsPerDay =
    1000 * 60 * 60 * 24;

  return Math.round(
    (end.getTime() - start.getTime()) /
    millisecondsPerDay
  );
};

// --------------------------------------------------
// 1. Deduplicate milestones by Milestone ID
// --------------------------------------------------

const uniqueMilestoneMap = new Map();

for (const milestone of rows) {
  const key =
    String(milestone['Milestone ID'] ?? '').trim() ||
    String(milestone.Milestone ?? '').trim();

  if (!key) continue;

  if (!uniqueMilestoneMap.has(key)) {
    uniqueMilestoneMap.set(key, milestone);
  }
}

const milestones = Array.from(
  uniqueMilestoneMap.values()
);

const duplicatesRemoved =
  rows.length - milestones.length;

// --------------------------------------------------
// 2. Completed and open milestones
// --------------------------------------------------

const completedMilestones = milestones.filter(milestone => {
  return normalize(milestone.Status) === 'completed';
});

const openMilestones = milestones.filter(milestone => {
  return normalize(milestone.Status) !== 'completed';
});

// --------------------------------------------------
// 3. Overdue milestones
// --------------------------------------------------

const overdueMilestones = openMilestones.filter(milestone => {
  const plannedDate =
    parseDate(milestone['Planned Date']);

  return plannedDate && plannedDate < today;
});

// --------------------------------------------------
// 4. Critical path milestones
// --------------------------------------------------

const criticalMilestones = milestones.filter(milestone => {
  return normalize(
    milestone['Critical Path']
  ) === 'yes';
});

const criticalOverdueMilestones =
  overdueMilestones.filter(milestone => {
    return normalize(
      milestone['Critical Path']
    ) === 'yes';
  });

// --------------------------------------------------
// 5. Forecast slippage
// --------------------------------------------------

const forecastDelayedMilestones =
  openMilestones.filter(milestone => {
    const plannedDate =
      parseDate(milestone['Planned Date']);

    const forecastDate =
      parseDate(milestone['Forecast Date']);

    if (!plannedDate || !forecastDate) {
      return false;
    }

    return forecastDate > plannedDate;
  });

const forecastDelayDays =
  forecastDelayedMilestones.map(milestone => {
    const plannedDate =
      parseDate(milestone['Planned Date']);

    const forecastDate =
      parseDate(milestone['Forecast Date']);

    return daysBetween(
      plannedDate,
      forecastDate
    );
  });

const averageForecastDelayDays =
  forecastDelayDays.length > 0
    ? forecastDelayDays.reduce(
        (sum, days) => sum + days,
        0
      ) / forecastDelayDays.length
    : 0;

const maximumForecastDelayDays =
  forecastDelayDays.length > 0
    ? Math.max(...forecastDelayDays)
    : 0;

// --------------------------------------------------
// 6. Completed milestones delivered late
// --------------------------------------------------

const completedLateMilestones =
  completedMilestones.filter(milestone => {
    const plannedDate =
      parseDate(milestone['Planned Date']);

    const actualDate =
      parseDate(milestone['Actual Date']);

    if (!plannedDate || !actualDate) {
      return false;
    }

    return actualDate > plannedDate;
  });

// --------------------------------------------------
// 7. Percentages
// --------------------------------------------------

const overduePercentage =
  openMilestones.length > 0
    ? (
        overdueMilestones.length /
        openMilestones.length
      ) * 100
    : 0;

// --------------------------------------------------
// 8. Overdue milestone penalty
// --------------------------------------------------

let overduePenalty = 0;

if (overduePercentage > 50) {
  overduePenalty = 40;
} else if (overduePercentage > 30) {
  overduePenalty = 30;
} else if (overduePercentage > 10) {
  overduePenalty = 20;
} else if (overduePercentage > 0) {
  overduePenalty = 10;
}

// --------------------------------------------------
// 9. Critical path penalty
// --------------------------------------------------

const criticalOverduePenalty = Math.min(
  criticalOverdueMilestones.length * 10,
  30
);

// --------------------------------------------------
// 10. Forecast delay penalty
// --------------------------------------------------

let forecastDelayPenalty = 0;

if (averageForecastDelayDays > 14) {
  forecastDelayPenalty = 20;
} else if (averageForecastDelayDays > 7) {
  forecastDelayPenalty = 15;
} else if (averageForecastDelayDays > 0) {
  forecastDelayPenalty = 10;
}

// --------------------------------------------------
// 11. Completed late penalty
// --------------------------------------------------

const completedLatePenalty = Math.min(
  completedLateMilestones.length * 10,
  20
);

// --------------------------------------------------
// 12. Final Schedule Health Score
// --------------------------------------------------

const scheduleScore = Math.max(
  0,
  100 -
    overduePenalty -
    criticalOverduePenalty -
    forecastDelayPenalty -
    completedLatePenalty
);

let scheduleStatus;

if (scheduleScore >= 80) {
  scheduleStatus = 'Green';
} else if (scheduleScore >= 60) {
  scheduleStatus = 'Amber';
} else {
  scheduleStatus = 'Red';
}

// --------------------------------------------------
// 13. Output
// --------------------------------------------------

return [
  {
    json: {
      assessment_date: assessmentDate,

      source_milestone_rows: rows.length,
      unique_milestones: milestones.length,
      duplicate_milestones_removed:
        duplicatesRemoved,

      completed_milestones:
        completedMilestones.length,

      open_milestones:
        openMilestones.length,

      overdue_milestones:
        overdueMilestones.length,

      overdue_percentage:
        Number(overduePercentage.toFixed(2)),

      critical_path_milestones:
        criticalMilestones.length,

      critical_overdue_milestones:
        criticalOverdueMilestones.length,

      forecast_delayed_milestones:
        forecastDelayedMilestones.length,

      average_forecast_delay_days:
        Number(
          averageForecastDelayDays.toFixed(2)
        ),

      maximum_forecast_delay_days:
        maximumForecastDelayDays,

      completed_late_milestones:
        completedLateMilestones.length,

      overdue_penalty:
        overduePenalty,

      critical_overdue_penalty:
        criticalOverduePenalty,

      forecast_delay_penalty:
        forecastDelayPenalty,

      completed_late_penalty:
        completedLatePenalty,

      schedule_score:
        scheduleScore,

      schedule_status:
        scheduleStatus
    }
  }
];

const rows = $input.all().map(item => item.json);

const now = new Date();

const assessmentDate = new Intl.DateTimeFormat('en-CA', {
  timeZone: 'Asia/Dubai',
  year: 'numeric',
  month: '2-digit',
  day: '2-digit'
}).format(now);

const toNumber = value => {
  const number = Number(value);
  return Number.isFinite(number) ? number : null;
};

// For Project 03 v1 we expect one financial record per project.
const financial = rows[0] ?? {};

const approvedBudget =
  toNumber(financial['Approved Budget']);

const actualCost =
  toNumber(financial['Actual Cost']);

const forecastAtCompletion =
  toNumber(financial['Forecast at Completion']);

const suppliedVariance =
  toNumber(financial['Budget Variance %']);

// Calculate variance independently so we don't blindly trust
// the manually entered percentage.
let calculatedVariance = null;

if (
  approvedBudget !== null &&
  approvedBudget > 0 &&
  forecastAtCompletion !== null
) {
  calculatedVariance =
    ((forecastAtCompletion - approvedBudget) /
      approvedBudget) *
    100;
}

// Prefer calculated variance when possible.
const budgetVariance =
  calculatedVariance !== null
    ? calculatedVariance
    : suppliedVariance;

// Validate the supplied sheet value against our calculation.
let varianceMismatch = false;

if (
  suppliedVariance !== null &&
  calculatedVariance !== null
) {
  varianceMismatch =
    Math.abs(
      suppliedVariance - calculatedVariance
    ) > 0.1;
}

// --------------------------------------------------
// Financial score
// --------------------------------------------------

let financialScore = 0;

if (budgetVariance === null) {
  financialScore = 0;
} else if (budgetVariance <= 0) {
  financialScore = 100;
} else if (budgetVariance <= 5) {
  financialScore = 80;
} else if (budgetVariance <= 10) {
  financialScore = 60;
} else if (budgetVariance <= 20) {
  financialScore = 40;
} else {
  financialScore = 20;
}

// --------------------------------------------------
// RAG
// --------------------------------------------------

let financialStatus;

if (financialScore >= 80) {
  financialStatus = 'Green';
} else if (financialScore >= 60) {
  financialStatus = 'Amber';
} else {
  financialStatus = 'Red';
}

// Current spend percentage is useful context,
// but it does NOT determine the score directly.
let budgetConsumedPercentage = null;

if (
  approvedBudget !== null &&
  approvedBudget > 0 &&
  actualCost !== null
) {
  budgetConsumedPercentage =
    (actualCost / approvedBudget) * 100;
}

return [
  {
    json: {
      assessment_date: assessmentDate,

      project_id:
        financial['Project ID'] ?? '',

      project:
        financial.Project ?? '',

      approved_budget:
        approvedBudget,

      actual_cost:
        actualCost,

      forecast_at_completion:
        forecastAtCompletion,

      budget_consumed_percentage:
        budgetConsumedPercentage !== null
          ? Number(
              budgetConsumedPercentage.toFixed(2)
            )
          : null,

      supplied_budget_variance_percentage:
        suppliedVariance,

      calculated_budget_variance_percentage:
        calculatedVariance !== null
          ? Number(
              calculatedVariance.toFixed(2)
            )
          : null,

      variance_mismatch:
        varianceMismatch,

      financial_score:
        financialScore,

      financial_status:
        financialStatus
    }
  }
];

const rows = $input.all().map(item => item.json);

const now = new Date();

const assessmentDate = new Intl.DateTimeFormat('en-CA', {
  timeZone: 'Asia/Dubai',
  year: 'numeric',
  month: '2-digit',
  day: '2-digit'
}).format(now);

const normalize = value =>
  String(value ?? '').trim().toLowerCase();

const parseDate = value => {
  if (!value) return null;

  const match = String(value).match(
    /^(\d{4})-(\d{2})-(\d{2})$/
  );

  if (match) {
    return new Date(
      Number(match[1]),
      Number(match[2]) - 1,
      Number(match[3])
    );
  }

  const date = new Date(value);

  if (Number.isNaN(date.getTime())) {
    return null;
  }

  return date;
};

const [year, month, day] =
  assessmentDate.split('-').map(Number);

const today = new Date(
  year,
  month - 1,
  day
);

const daysBetween = (start, end) => {
  const msPerDay = 1000 * 60 * 60 * 24;

  return Math.round(
    (end.getTime() - start.getTime()) /
    msPerDay
  );
};

const governance = rows[0] ?? {};

// --------------------------------------------------
// 1. Status report compliance
// --------------------------------------------------

const statusReportDue =
  parseDate(governance['Status Report Due Date']);

const statusReportSubmitted =
  parseDate(governance['Status Report Submitted Date']);

let statusReportLate = false;
let statusReportOverdue = false;
let statusReportDelayDays = 0;

if (statusReportDue) {
  if (statusReportSubmitted) {
    statusReportLate =
      statusReportSubmitted > statusReportDue;

    if (statusReportLate) {
      statusReportDelayDays =
        daysBetween(
          statusReportDue,
          statusReportSubmitted
        );
    }
  } else if (statusReportDue < today) {
    statusReportOverdue = true;

    statusReportDelayDays =
      daysBetween(
        statusReportDue,
        today
      );
  }
}

// --------------------------------------------------
// 2. RAID review compliance
// --------------------------------------------------

const raidReviewDue =
  parseDate(governance['RAID Review Due Date']);

const raidReviewCompleted =
  parseDate(governance['RAID Review Completed Date']);

const raidReviewOverdue =
  raidReviewDue &&
  !raidReviewCompleted &&
  raidReviewDue < today;

// --------------------------------------------------
// 3. Steering Committee compliance
// --------------------------------------------------

const steercoDue =
  parseDate(
    governance['Steering Committee Due Date']
  );

const steercoHeld =
  parseDate(
    governance['Steering Committee Held Date']
  );

const steercoMissed =
  steercoDue &&
  !steercoHeld &&
  steercoDue < today;

// --------------------------------------------------
// 4. Pending decisions
// --------------------------------------------------

const pendingDecisions =
  Number(governance['Pending Decisions'] ?? 0);

// --------------------------------------------------
// 5. Mandatory data completeness
// --------------------------------------------------

const mandatoryFieldsComplete =
  normalize(
    governance['Mandatory Fields Complete']
  ) === 'yes';

// --------------------------------------------------
// 6. Penalties
// --------------------------------------------------

let statusReportPenalty = 0;

if (statusReportOverdue) {
  statusReportPenalty = 20;
} else if (statusReportLate) {
  statusReportPenalty = 10;
}

const raidReviewPenalty =
  raidReviewOverdue ? 20 : 0;

const steeringCommitteePenalty =
  steercoMissed ? 20 : 0;

let pendingDecisionPenalty = 0;

if (pendingDecisions >= 5) {
  pendingDecisionPenalty = 20;
} else if (pendingDecisions >= 3) {
  pendingDecisionPenalty = 15;
} else if (pendingDecisions > 0) {
  pendingDecisionPenalty = 10;
}

const mandatoryFieldsPenalty =
  mandatoryFieldsComplete ? 0 : 15;

// --------------------------------------------------
// 7. Final Governance Health Score
// --------------------------------------------------

const governanceScore = Math.max(
  0,
  100 -
    statusReportPenalty -
    raidReviewPenalty -
    steeringCommitteePenalty -
    pendingDecisionPenalty -
    mandatoryFieldsPenalty
);

let governanceStatus;

if (governanceScore >= 80) {
  governanceStatus = 'Green';
} else if (governanceScore >= 60) {
  governanceStatus = 'Amber';
} else {
  governanceStatus = 'Red';
}

// --------------------------------------------------
// 8. Output
// --------------------------------------------------

return [
  {
    json: {
      assessment_date: assessmentDate,

      project_id:
        governance['Project ID'] ?? '',

      project:
        governance.Project ?? '',

      status_report_late:
        statusReportLate,

      status_report_overdue:
        statusReportOverdue,

      status_report_delay_days:
        statusReportDelayDays,

      raid_review_overdue:
        Boolean(raidReviewOverdue),

      steering_committee_missed:
        Boolean(steercoMissed),

      pending_decisions:
        pendingDecisions,

      mandatory_fields_complete:
        mandatoryFieldsComplete,

      status_report_penalty:
        statusReportPenalty,

      raid_review_penalty:
        raidReviewPenalty,

      steering_committee_penalty:
        steeringCommitteePenalty,

      pending_decision_penalty:
        pendingDecisionPenalty,

      mandatory_fields_penalty:
        mandatoryFieldsPenalty,

      governance_score:
        governanceScore,

      governance_status:
        governanceStatus
    }
  }
];

const items = $input.all().map(item => item.json);

// Merge all component outputs into one object
const data = Object.assign({}, ...items);

const scheduleScore =
  Number(data.schedule_score ?? 0);

const raidScore =
  Number(data.raid_score ?? 0);

const actionScore =
  Number(data.action_score ?? 0);

const financialScore =
  Number(data.financial_score ?? 0);

const governanceScore =
  Number(data.governance_score ?? 0);

// --------------------------------------------------
// 1. Weighted overall score
// --------------------------------------------------

const overallScoreRaw =
  scheduleScore * 0.25 +
  raidScore * 0.25 +
  actionScore * 0.20 +
  financialScore * 0.15 +
  governanceScore * 0.15;

const overallScore =
  Math.round(overallScoreRaw);

// --------------------------------------------------
// 2. Base RAG status
// --------------------------------------------------

let calculatedOverallStatus;

if (overallScore >= 80) {
  calculatedOverallStatus = 'Green';
} else if (overallScore >= 60) {
  calculatedOverallStatus = 'Amber';
} else {
  calculatedOverallStatus = 'Red';
}

// --------------------------------------------------
// 3. Critical overrides
// --------------------------------------------------

// Critical issue already identified in RAID logic
const criticalIssues =
  Number(data.critical_issues ?? 0);

const raidCriticalOverride =
  data.critical_override === true;

// Severe schedule condition
const scheduleCriticalOverride =
  scheduleScore < 30;

// Severe financial condition
const financialCriticalOverride =
  financialScore < 30;

// Overall override
const criticalOverride =
  raidCriticalOverride ||
  scheduleCriticalOverride ||
  financialCriticalOverride;

// Final status
const overallStatus =
  criticalOverride
    ? 'Red'
    : calculatedOverallStatus;

// --------------------------------------------------
// 4. Identify weakest / strongest components
// --------------------------------------------------

const components = [
  {
    name: 'Schedule',
    score: scheduleScore
  },
  {
    name: 'RAID',
    score: raidScore
  },
  {
    name: 'Actions',
    score: actionScore
  },
  {
    name: 'Financial',
    score: financialScore
  },
  {
    name: 'Governance',
    score: governanceScore
  }
];

components.sort(
  (a, b) => a.score - b.score
);

const weakestComponent =
  components[0];

const secondWeakestComponent =
  components[1];

const strongestComponent =
  components[components.length - 1];

// --------------------------------------------------
// 5. Output
// --------------------------------------------------

return [
  {
    json: {
      assessment_date:
        data.assessment_date,

      project_id:
        data.project_id ||
        data['Project ID'] ||
        'PRJ-001',

      project:
        data.project ||
        data.Project ||
        'CRM Implementation',

      schedule_score:
        scheduleScore,

      raid_score:
        raidScore,

      action_score:
        actionScore,

      financial_score:
        financialScore,

      governance_score:
        governanceScore,

      schedule_weight: 25,
      raid_weight: 25,
      action_weight: 20,
      financial_weight: 15,
      governance_weight: 15,

      overall_health_score:
        overallScore,

      calculated_overall_status:
        calculatedOverallStatus,

      critical_issues:
        criticalIssues,

      raid_critical_override:
        raidCriticalOverride,

      schedule_critical_override:
        scheduleCriticalOverride,

      financial_critical_override:
        financialCriticalOverride,

      critical_override:
        criticalOverride,

      overall_status:
        overallStatus,

      weakest_component:
        weakestComponent.name,

      weakest_component_score:
        weakestComponent.score,

      second_weakest_component:
        secondWeakestComponent.name,

      second_weakest_component_score:
        secondWeakestComponent.score,

      strongest_component:
        strongestComponent.name,

      strongest_component_score:
        strongestComponent.score
    }
  }
];

