const item = $input.first().json;

let parsed;

try {
  parsed = JSON.parse(item.output);
} catch (error) {
  throw new Error(
    `Failed to parse AI executive health JSON: ${error.message}`
  );
}

const requiredFields = [
  'executive_summary',
  'top_health_drivers',
  'recommended_actions',
  'management_attention'
];

for (const field of requiredFields) {
  if (!(field in parsed)) {
    throw new Error(
      `Missing required AI output field: ${field}`
    );
  }
}

if (!Array.isArray(parsed.top_health_drivers)) {
  throw new Error(
    'top_health_drivers must be an array'
  );
}

if (!Array.isArray(parsed.recommended_actions)) {
  throw new Error(
    'recommended_actions must be an array'
  );
}

return [
  {
    json: {
      executive_summary:
        parsed.executive_summary,

      health_driver_1:
        parsed.top_health_drivers[0] ?? '',

      health_driver_2:
        parsed.top_health_drivers[1] ?? '',

      health_driver_3:
        parsed.top_health_drivers[2] ?? '',

      recommended_action_1:
        parsed.recommended_actions[0] ?? '',

      recommended_action_2:
        parsed.recommended_actions[1] ?? '',

      recommended_action_3:
        parsed.recommended_actions[2] ?? '',

      management_attention:
        parsed.management_attention
    }
  }
];

const history = $input.all().map(item => item.json);

// Current assessment comes from the deterministic scoring node
const current =
  $('20 - Calculate Overall Project Health')
    .first()
    .json;

const currentScore =
  Number(current.overall_health_score ?? 0);

// Sort historical assessments newest first
history.sort((a, b) => {
  const idA = String(a['Assessment ID'] ?? '');
  const idB = String(b['Assessment ID'] ?? '');

  return idB.localeCompare(idA);
});

// Most recent existing assessment
const previous = history[0] ?? null;

let previousScore = null;
let scoreChange = null;
let trend = 'First Assessment';

if (previous) {
  previousScore =
    Number(previous['Overall Health Score']);

  scoreChange =
    currentScore - previousScore;

  if (scoreChange > 0) {
    trend = 'Improving';
  } else if (scoreChange < 0) {
    trend = 'Deteriorating';
  } else {
    trend = 'Stable';
  }
}

return [
  {
    json: {
      previous_score: previousScore,
      score_change: scoreChange,
      trend: trend
    }
  }
];

const historyRows = $input.all().map(item => item.json);

// Current project-health object comes from node 27
const current =
  $('27 - Merge Complete Health Record')
    .first()
    .json;

const assessmentDate =
  current.assessment_date ?? '';

const projectId =
  current.project_id ?? '';

const project =
  current.project ?? '';

const overallScore =
  Number(current.overall_health_score ?? 0);

const previousScore =
  current.previous_score !== null &&
  current.previous_score !== undefined
    ? Number(current.previous_score)
    : null;

const scoreChange =
  current.score_change !== null &&
  current.score_change !== undefined
    ? Number(current.score_change)
    : null;

const overallStatus =
  String(current.overall_status ?? '');

const criticalOverride =
  current.critical_override === true;

// --------------------------------------------------
// 1. Determine current alert type
// --------------------------------------------------

let alertType = '';
let alertReason = '';

if (
  scoreChange !== null &&
  scoreChange <= -10
) {
  alertType = 'SCORE_DROP';
  alertReason =
    `Project health score deteriorated by ${Math.abs(scoreChange)} points.`;
} else if (criticalOverride) {
  alertType = 'CRITICAL_OVERRIDE';
  alertReason =
    'Project health has an active critical override.';
} else if (overallStatus === 'Red') {
  alertType = 'RED_STATUS';
  alertReason =
    'Project health status is Red.';
}

// --------------------------------------------------
// 2. Build stable alert key
// --------------------------------------------------

const alertKey =
  `${projectId}|${alertType}`;

// --------------------------------------------------
// 3. Remove empty placeholder items
// --------------------------------------------------

const validHistoryRows =
  historyRows.filter(row => {
    return Object.keys(row).length > 0;
  });

// --------------------------------------------------
// 4. Check whether same alert was already sent
// --------------------------------------------------

const matchingAlert =
  validHistoryRows.find(row => {
    const existingKey =
      String(row['Alert Key'] ?? '').trim();

    const existingStatus =
      String(row['Alert Status'] ?? '')
        .trim()
        .toUpperCase();

    return (
      existingKey === alertKey &&
      existingStatus === 'SENT'
    );
  });

// --------------------------------------------------
// 5. Decide whether to send
// --------------------------------------------------

const sendAlert =
  Boolean(alertType) &&
  !matchingAlert;

// --------------------------------------------------
// 6. Generate alert ID
// --------------------------------------------------

const now = new Date();

const timestamp =
  new Intl.DateTimeFormat('en-CA', {
    timeZone: 'Asia/Dubai',
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
    hour: '2-digit',
    minute: '2-digit',
    second: '2-digit',
    hour12: false
  })
    .format(now)
    .replace(/[^\d]/g, '');

const alertId =
  `ALT-${projectId}-${timestamp}`;

// --------------------------------------------------
// 7. Output
// --------------------------------------------------

return [
  {
    json: {
      alert_id: alertId,
      assessment_id: '',
      assessment_date: assessmentDate,

      project_id: projectId,
      project: project,

      alert_type: alertType,
      alert_key: alertKey,
      alert_reason: alertReason,

      overall_health_score:
        overallScore,

      previous_score:
        previousScore,

      score_change:
        scoreChange,

      rag_status:
        overallStatus,

      critical_override:
        criticalOverride,

      duplicate_alert_found:
        Boolean(matchingAlert),

      send_alert:
        sendAlert,

      alert_status:
        sendAlert
          ? 'READY_TO_SEND'
          : 'SUPPRESSED'
    }
  }
];
